function store1Home(lang='en',t={},formatMoney=null){
 const c=store1Copy[lang]||store1Copy.en,root=lang==='en'?'':'/'+lang;
 const a=(label,url,cls='btn')=>`<a class="${cls}" href="${root+url}" data-route>${label}</a>`;
 const money=n=>`<span data-money-usd="${n}">${formatMoney?formatMoney(n):'$'+n.toLocaleString('en-US')}</span>`;
 const route=(label,url,cls='text-link')=>a(label,url,cls);
 return `<section class="s1-hero"><div class="s1-hero-copy"><span class="eyebrow">QUICKMIND HOME · YIWEI MEDICAL</span><h1>${c[0]}</h1><p>${c[1]}</p><div class="buttons">${a(c[2],'/home-product/')} ${a(c[3],'/pricing/','btn outline')}</div><div class="s1-hero-price"><strong>${money(2498)}</strong><span>${c[22]}</span></div></div><div class="s1-hero-image"><img src="/assets/headset.webp" width="1440" height="1440" fetchpriority="high" alt="QuickMind VR headset and illustrative screen"><span class="s1-image-note">${c[34]}</span></div></section>
 <div class="s1-service"><a href="${root}/pricing/" data-route>${c[20]} + ${c[21]}</a><a href="${root}/pages/contact/" data-route>${t.delivery||'Confirm delivery in your country'}</a><a href="${root}/pages/registrations/" data-route>${t.registrations||'Product-specific conformity records'}</a></div>
 <section class="section container s1-paths"><span class="eyebrow">QUICKMIND</span><h2>${c[4]}</h2><div class="s1-path-grid">${[[5,8,'/home-product/','headset.webp','home'],[6,9,'/pages/contact/?intent=clinic','scenarios/singapore-demo.webp','clinic'],[7,10,'/pages/contact/?intent=distributor','scenarios/indonesia-team.webp','distributor']].map(([title,desc,url,img,id])=>`<a class="s1-path" href="${root+url}" data-route data-source="QM1-${lang}-path-${id}"><img src="/assets/${img}" width="600" height="450" loading="lazy" alt="${c[title]}"><div><h3>${c[title]}</h3><p>${c[desc]}</p><span aria-hidden="true">↗</span></div></a>`).join('')}</div></section>
 <section class="s1-feature"><div class="s1-feature-image"><img src="/assets/games.webp" width="803" height="697" loading="lazy" alt="QuickMind activity previews"></div><div class="s1-feature-copy"><span class="eyebrow">QUICKMIND HOME</span><h2>${c[38]}</h2><p>${c[33]}</p><div class="s1-tags"><span>${c[35]}</span><span>${c[36]}</span><span>${c[37]}</span></div>${a(c[32],'/home-product/','text-link')}<small>${c[34]}</small></div></section>
 <section class="section container"><span class="eyebrow">HOME ROUTINE</span><h2>${c[11]}</h2><div class="s1-steps">${[12,13,14].map((i,n)=>`<article><span>0${n+1}</span><h3>${c[i]}</h3><p>${c[i+3]}</p></article>`).join('')}</div></section>
 <section class="s1-plan section"><div class="container s1-plan-grid"><div><span class="eyebrow">QUICKMIND HOME PLAN</span><h2>${c[18]}</h2><p>${c[19]}</p><p class="fine">${c[23]}</p>${a(c[3],'/pricing/','text-link')}</div><div class="s1-price-card"><div><span>${c[20]}</span><b>${money(499)}</b></div><div><span>${c[21]}</span><b>${money(1999)}</b></div><div class="s1-total"><span>${c[22]}</span><strong>${money(2498)}</strong></div>${a(c[31],'/pages/contact/')}<small>${t.priceNote||'Proposed offer. Configuration, delivery and total are confirmed by written quotation.'}</small></div></div></section>
 <section class="section container s1-science"><div><span class="eyebrow">EVIDENCE & DOCUMENTS</span><h2>${c[24]}</h2><p>${c[25]}</p><div class="buttons">${a(c[26],'/pages/clinical-evidence/','btn outline')}${a(c[27],'/pages/registrations/','text-link')}</div></div><div class="s1-science-image"><img src="/assets/report.webp" width="860" height="1022" loading="lazy" alt="Original QuickMind assessment report illustration"><small>${t.researchNote||'Assessment-report illustration; not an included diagnostic feature of the Home Plan.'}</small></div></section>
 <section class="s1-help section"><div class="container"><span class="eyebrow">SUPPORT FOR YOUR DECISION</span><h2>${c[28]}</h2><p>${c[29]}</p><div class="buttons">${a(c[30],'/pages/faq/','btn outline')}${a(t.compare||'Compare home & clinic','/pages/compare/','text-link')}${a(c[31],'/pages/contact/')}</div></div></section>`;
}
if(typeof module!=='undefined')module.exports={store1Home};
